function pick(obj, keys) {
  const out = {}
  for (const k of keys) if (Object.hasOwn(obj, k)) out[k] = obj[k]
  return out
}
function omit(obj, keys) {
  const out = { ...obj }
  for (const k of keys) delete out[k]
  return out
}

